text:
  flex-direction: column;
  gap: var(--hub-space-small);

  tb-banner a {
    color: inherit;
  }
}

div:has(legend) {
  display: flex;
}

.input-control {
  display: flex;
  align-items: center;
  position: relative;

  &:has(label.animated) {
    padding-block-start: calc(var(--hub-form-label-height) - var(--hub-form-input-block-padding));
  }

  /* Hide the helper text if there is a visible error message, as it will
   * errantly visually overlap otherwise. Use 'visibility' to avoid
   * element collapse and incorrect spacing. */
  &:has(:is(:user-invalid, [aria-invalid="true"], .warning) ~ .input-error-message) + .account-hub-form-small-comment {
    visibility: hidden;
  }

  &:has(.security-warning) {
    flex-wrap: wrap;
  }
}

.input-control.vertical {
  flex-direction: column;
  align-items: stretch;
}

.form-icon {
  inline-size: 16px;
  block-size: 16px;

  input:is(:user-invalid, :invalid) ~ & {
    display: none;
  }
